briefCalls.responseText:
{
  "primitive": "intro_briefing",
  "topic": "Extend ordinal number understanding to tenth position (sixth through tenth)",
  "subject": "General",
  "gradeLevel": "kindergarten",
  "estimatedTime": "15-20 minutes",
  "hook": {
    "type": "scenario",
    "content": "Imagine you are lining up all your favorite stuffed animals for a big parade! The teddy bear is first, the bunny is second... but who is all the way at the very end in the tenth spot?",
    "visualTheme": "counting"
  },
  "bigIdea": {
    "statement": "Ordinal numbers help us tell the exact order or place of things in a line, going all the way from first up to tenth!",
    "whyItMatters": "We use ordinal numbers every day when we wait in the lunch line, race on the playground, or talk about our favorite books in a series."
  },
  "objectives": [
    {
      "id": "obj1",
      "text": "Arrange a line of up to ten real objects in order from first to tenth",
      "verb": "apply",
      "icon": "puzzle"
    },
    {
      "id": "obj2",
      "text": "Identify the sixth through tenth positions using ordinal number words",
      "verb": "identify",
      "icon": "search"
    },
    {
      "id": "obj3",
      "text": "Explain who is in a specific spot when looking at a lined-up group of ten items",
      "verb": "explain",
      "icon": "message"
    }
  ],
  "prerequisites": {
    "shouldKnow": [
      "Counting objects from 1 to 10 in the correct order",
      "Using basic ordinal words like first, second, third, fourth, and fifth"
    ],
    "quickCheck": {
      "question": "If you have a line of toys, what word do we use for the toy that comes right after fourth?",
      "answer": "Fifth",
      "hint": "Count up from one: first, second, third, fourth..."
    }
  },
  "roadmap": [
    {
      "phase": "Explore",
      "description": "Look at toy lines and practice counting up to five.",
      "activities": [
        "Line up five blocks",
        "Review first through fifth positions"
      ]
    },
    {
      "phase": "Learn",
      "description": "Discover new ordinal words for spots six through ten.",
      "activities": [
        "Count from sixth to tenth in a special animal parade",
        "Practice saying sixth, seventh, eighth, ninth, and tenth out loud"
      ]
    },
    {
      "phase": "Practice",
      "description": "Play games to find the right spot in a big group.",
      "activities": [
        "Find the eighth toy in a row",
        "Point to the tenth item in a picture"
      ]
    },
    {
      "phase": "Apply",
      "description": "Show what you know by building your own ten-item line.",
      "activities": [
        "Create a sticker train with ten cars",
        "Name the position of each sticker car"
      ]
    }
  ],
  "connections": {
    "buildingFrom": [
      "Counting numbers 1-10",
      "Basic ordinal numbers first through fifth"
    ],
    "leadingTo": [
      "Using ordinal numbers in calendar skills",
      "Solving longer sequencing and pattern problems"
    ],
    "realWorld": [
      "Finding your place in a school line",
      "Finding floors in a building",
      "Racing friends on the playground"
    ]
  },
  "mindset": {
    "encouragement": "Learning big new words like 'seventh' and 'tenth' can be tricky, but you are going to be great at it!",
    "growthTip": "Take it one step at a time! Touch each object slowly as you count: sixth, seventh, eighth, ninth, tenth."
  }
}
